window.kbPageData["views/entry/k-6565cf5a5e9a8a37"] = {"key":"entry/k-6565cf5a5e9a8a37","state":{"route":"entry/k-6565cf5a5e9a8a37"},"node":{"id":"k-6565cf5a5e9a8a37","mode":"k","title":"比较优势","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["两种产品的比较优势取决于相对生产效率"],"qs":["国考 2025 副省级 行测#73"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"一个生产者生产某种产品的机会成本低于另一生产者，就在该产品上具有比较优势。机会成本可用生产一单位该产品所放弃的另一种产品产量来衡量。","review":{"definition":"一个生产者生产某种产品的机会成本低于另一生产者，就在该产品上具有比较优势。机会成本可用生产一单位该产品所放弃的另一种产品产量来衡量。","explanation":"甲每生产1个A模块少产0.5个B模块，乙则少产2个B模块，因此由甲优先生产A。把每天的产量折为B模块当量，每个A计0.5、每个B计1，甲每天最多产3个当量，乙最多产2个。120个A和80个B共需140个当量，至少要28天。前20天甲生产120个A、乙生产40个B，随后两车间合产8天补足40个B，达到这个下限。","references":[],"evidence":"甲车间生产A模块的相对效率更高","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#73":{"paper":"国考 2025 副省级 行测","n":73,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",12],"asrc":["ff0b352b44d417525086.pdf",22],"card":"3dba14b22c1e8770554d3e9d","links":[{"id":"k-6565cf5a5e9a8a37","role":"解题依据","why":"在生产时间可调配时，比较同一车间在两种产品上的相对效率，能判断把哪种产品优先交给它生产更节省工时。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-6565cf5a5e9a8a37":[["国考 2025 副省级 行测#73"]]}};
